public sealed class ImagePlanService(InstallConfig config,AiAccounts accounts,WorkspaceService workspace){
 readonly SemaphoreSlim gate=new(1,1);
 public async Task<JObject> SaveReviewedDraft(string sourceId,string analysisHash,JObject reply,CancellationToken ct)
 {
  if(!await gate.WaitAsync(0,ct))throw new CadException("AI_BUSY","Đang dựng nguồn.");
  try
  {
   string path=workspace.Intelligence.AnalysisPath(Json.Id(sourceId));
   string pathHash=Json.FileHash(path);
   if(pathHash!=analysisHash)throw new CadException("SOURCE_CHANGED","Bản nháp đã thay đổi, tải lại trước khi chỉnh.");
   var model=Json.Read<JObject>(File.ReadAllText(path));
   var review=model["reviewMetadata"] as JObject??throw new CadException("NEEDS_CALIBRATION","Cần bản nháp đã hiệu chuẩn.");
   var meta=Json.Read<JObject>(File.ReadAllText(Path.Combine(workspace.Intelligence.Folder,sourceId+".json")));
   string source=Path.Combine(workspace.Intelligence.Folder,sourceId+Path.GetExtension(meta.Value<string>("name")??""));
   if(Json.FileHash(source)!=meta.Value<string>("hash")||Json.FileHash(path)!=pathHash)
    throw new CadException("SOURCE_CHANGED","Nguồn ảnh hoặc bản nháp đã thay đổi.");
   var template=workspace.Template(review.Value<string>("templateId")??"");
   var skill=workspace.Store.Skill(review.Value<string>("skillId")??"");
   if(skill.TemplateId!=template.Id||skill.Id!=ResidentialSourcePlan.SkillId||!workspace.Store.Enabled(skill.Id))
    throw new CadException("SKILL_MISMATCH","Cần Skill nhà ở Quang Anh đang hoạt động.");
   if(reply["operations"] is not JArray||reply["assumptions"] is not JArray)
    throw new CadException("INVALID_DRAFT","Cần thao tác CAD và ghi chú kiểm tra.");
   return SaveDraft(sourceId,review.Value<double>("widthMm"),review.Value<double>("heightMm"),
       (JObject)review["imageRect"]!,template,skill,reply,new(),meta,model,"REVIEWED_IMAGE_DRAFT");
  }
  finally{gate.Release();}
 }
 public JObject Finalize(string id,string rotationUnits){
  if(rotationUnits!="degrees"&&rotationUnits!="radians")throw new CadException("INVALID_ROTATION_UNITS","Chọn radians hoặc degrees.");
  string path=workspace.Intelligence.AnalysisPath(Json.Id(id));var model=Json.Read<JObject>(File.ReadAllText(path));if(model["reviewOperations"] is not JArray)throw new CadException("NEEDS_IMAGE_PLAN","App chưa có kế hoạch ảnh.");
  if(model["reviewMetadata"]?.Value<bool?>("normalized")==true)return model;
  string backup=Path.Combine(workspace.Intelligence.Folder,id+".ai-original.json");if(!File.Exists(backup))File.Copy(path,backup);
  var ops=model["reviewOperations"]!.ToObject<List<Operation>>()!;var labels=new Dictionary<string,string>{{"STAIR","CAU THANG"},{"ALTAR","P THO"},{"BEDROOM 1","PHONG NGU 1"},{"BEDROOM 2","PHONG NGU 2"},{"BALCONY","BAN CONG"},{"HALL","HANH LANG"}};
  foreach(var op in ops){if(rotationUnits=="degrees")op.Rotation*=Math.PI/180;if(op.Kind=="add_text"){if(labels.TryGetValue(op.Text,out var label))op.Text=label;else if(op.Text.StartsWith("SOURCE TRACE"))op.Text="BAN THU THEO ANH - KICH THUOC BAO DA XAC NHAN";else if(op.Text.StartsWith("INTERNAL SIZES"))op.Text="TUONG, CUA, NOI THAT THEO TY LE ANH - CAN KIEM TRA";else if(op.Text.StartsWith("DOOR_900:"))op.Text="CUA DOOR_900: RONG 900 mm UOC LUONG";else if(op.Text.StartsWith("STAIR PLAN ONLY"))op.Text="CAU THANG CHI VE MAT BANG - CHUA CO CHIEU CAO";}}
  var t=workspace.Template(model["reviewMetadata"]?.Value<string>("templateId")??"ARCHITECTURE");foreach(var op in ops)Validation.Operation(op,t,true);var bounds=ops.SelectMany(o=>Validation.Bounds(o,t)).ToList();model["reviewOperations"]=JArray.FromObject(ops);model["bounds"]=JObject.FromObject(new{minX=bounds.Min(p=>p.X),minY=bounds.Min(p=>p.Y),maxX=bounds.Max(p=>p.X),maxY=bounds.Max(p=>p.Y)});
  model["reviewMetadata"]!["normalized"]=true;model["reviewMetadata"]!["inputRotationUnits"]=rotationUnits;model["reviewMetadata"]!["rotationUnits"]="radians";model["reviewSummary"]="Bản thử theo ảnh: "+ops.Count+" thao tác, "+ops.Count(o=>o.Kind=="insert_block")+" block từ thư viện "+t.Id+". Chi tiết bên trong cần kiểm tra.";
  Json.Atomic(path,model);string metaPath=Path.Combine(workspace.Intelligence.Folder,id+".json");var meta=Json.Read<JObject>(File.ReadAllText(metaPath));meta["analysisHash"]=Json.FileHash(path);Json.Atomic(metaPath,meta);return model;
 }
 public async Task<JObject> Build(string sourceId,double width,double height,JObject imageRect,bool confirmed,CancellationToken ct,string templateId="ARCHITECTURE",string skillId="SOURCE_FLOORPLAN",string? templateVersion=null,string? skillVersion=null){
  if(!confirmed||width<1000||width>100000||height<1000||height>100000)throw new CadException("NEEDS_CALIBRATION","Xác nhận kích thước bao trước khi dựng ảnh.");
  if(!await gate.WaitAsync(0,ct))throw new CadException("AI_BUSY","Đang dựng một ảnh khác.");
  try{
   var profile=accounts.Active()??throw new CadException("AI_LOGIN_REQUIRED","Kết nối tài khoản AI trong app trước.");
   if(!await accounts.LoggedIn(profile,ct))throw new CadException("AI_LOGIN_REQUIRED","Phiên AI cần đăng nhập lại.");long epoch=accounts.Epoch;
   string metadata=Path.Combine(workspace.Intelligence.Folder,Json.Id(sourceId)+".json");var meta=Json.Read<JObject>(File.ReadAllText(metadata));string extension=Path.GetExtension(meta.Value<string>("name")??"").ToLowerInvariant();
   if(!new[]{".png",".jpg",".jpeg"}.Contains(extension))throw new CadException("UNSUPPORTED_SOURCE","Bước thử này nhận ảnh PNG/JPEG.");
   string source=Path.Combine(workspace.Intelligence.Folder,sourceId+extension);if(Json.FileHash(source)!=meta.Value<string>("hash"))throw new CadException("SOURCE_CHANGED","Ảnh nguồn đã thay đổi.");
   string analysisPath=workspace.Intelligence.AnalysisPath(sourceId);var model=Json.Read<JObject>(File.ReadAllText(analysisPath));
   var template=workspace.Store.Template(templateId,templateVersion);var skill=workspace.Store.Skill(skillId,skillVersion);if(skill.TemplateId!=template.Id||skill.Builder!="source"||!workspace.Store.Enabled(skill.Id))throw new CadException("SKILL_MISMATCH","Skill ảnh phải được bật và liên kết đúng thư viện đã chọn.");
   var planningTemplate=Json.Read<TemplateProfile>(Json.Write(template));if(skill.Recipe!=null)planningTemplate.Blocks=planningTemplate.Blocks.Where(b=>skill.Recipe.AllowedBlocks.Contains(b.Id)||b.Usage!=null).ToList();
   var context=new{draftOnly=true,confirmedFootprintMm=new{width,height},imageRect,template=planningTemplate,skill,ocr=model["texts"],tools=Validation.Tools};
   string prompt="You are the image-to-CAD planner inside AI CAD. Use the attached floor-plan image and ONLY the supplied app template/skill libraries. Return the JSON schema, no tool calls. Produce a useful detailed 2D architectural floor plan, not a bounding rectangle: outer walls with door/window breaks, and the partitions, stair treads, voids, room fixtures and furniture that actually appear in this source. Preserve visible stair voids and align flights and landings to the inside faces of adjoining walls where the image shows contact. Use existing template layers, insert_block using the selected template native block assets for doors, beds, altar, WC and windows whenever suitable. Use ONLY asset IDs actually present. Native block extents in NativeSource.Min/Max are relative to insertion point; account for them and Rotation. Block scale is fixed at 1, no scaling or mirroring is supported. This stage creates a DRAFT only, never CAD writes. Catalog candidates with Usage.Reviewed=false may appear in the draft at their declared default visibility and parameters, on Usage.Layer; disclose that selection and dimensions require review. For candidates without confirmed width conversion, OpeningWidth must be null and do not change the width parameter via DynamicJson. Prefer reviewed allowed assets. If suitable furniture assets are absent, draw approximate primitive symbols and disclose the missing catalog mapping. OpeningWidth means masonry rough opening; set only when ConversionConfirmed=true. Never guess a conversion. For QA_CUA_SO_1_CANH use the fixed catalog DT. Omit DT from DynamicJson and set WallThickness to null for this asset. Native parameters are declared in NativeSource.DynamicProperties; DynamicJson is a JSON object string of permitted parameter values. DynamicJson, OpeningWidth and WallThickness MUST be null for every operation except insert_block. Use null, not 0 or an empty object string. Use ONLY tools declared in skill.RequiredTools. When draw_wall is declared, use draw_wall with two centerline endpoints and Height=220 for exterior walls or 110 for partitions; split centerlines at openings. If skill.Recipe exists, obey its layer roles and wall rules. In this draft stage, candidate catalog entries explicitly supplied in template.Blocks may also be used outside Recipe.AllowedBlocks; they require catalog review before any CAD plan can be created. Do not draw axes: the app adds only confirmed axes from the recipe. Do NOT draw a duplicate primitive furniture/door outline over an inserted native block. Use native assets for items present in this source and appropriate to the available catalog; avoid whole-room composite assets. Use draw_wall for walls when declared in the Skill; use primitive lines for staircase and details absent from the selected library, and native add_dimension for the two CONFIRMED overall dimensions; set Text to an empty string so dimensions report their measured length. Existing other dimension annotations can be added only when unambiguous and consistent. All Rotation values MUST be radians, never degrees; set rotationUnits to radians. Use Vietnamese ASCII room labels such as PHONG NGU 1, P THO, CAU THANG, BAN CONG. Coordinates: bottom-left of the overall building is (0,0); x right and y up, WCS mm. Outer building footprint must be exactly width by height supplied. Derive approximate relative layout from pixels in imageRect; use the confirmed footprint in CONTEXT and do not copy dimensions or layout from other drawings. Put dimensions outside the perimeter. Trace actual rooms, door locations, windows, staircase, furniture and sanitary fixtures from the image; do not introduce unrelated architecture. For each faÃ§ade, inspect the source in reading order and match every opening to its two visible jambs before generating wall segments. A window is the full span between its jambs; do not split a long window into repeated short blocks, infer openings from grid marks or columns, or treat an exterior walkway edge or parallel annotation as the wall face. Compute the wall breaks and window insertions from the same endpoints, with each block aligned along its wall and its frame inside the wall thickness. A door needs visible leaf or swing evidence; preserve adjacent solid wall where opening evidence is absent. Use plain ASCII room names and short notes using the supplied template font. Include a note that internal dimensions, wall thickness, openings and furniture are inferred from a low-resolution image and require review. Do not treat the template's stair preset as source measurements; no new section or guessed floor-to-floor height. Use at most 350 operations. Keep all labels short and readable (height about 100 mm); coordinate extents within -1500..width+1500 and -1500..height+1800. Include a clear assumptions list. No CAD approval or writes are possible here.\nCONTEXT:\n"+Json.Write(context);
   if(skill.Id==ResidentialSourcePlan.SkillId)prompt+="\nFor each door or window inserted from the approved catalog with a confirmed width conversion, provide one openingEvidence entry. Use the zero-based operationIndex, mark frame_between_jambs for windows or leaf_or_swing for doors, and pixelA/pixelB at the two visible jambs in the original image. Set jambA/jambB to the matching two endpoints on the wall centerline in CAD mm. The opening width must match the jamb-to-jamb distance. Keep the cut and block on the same wall. If either jamb or type is unclear, leave the position in assumptions with a nearby room or wall name; do not insert an assumed opening block. Other source skills may return an empty openingEvidence array.";
   prompt+="\nValidate the outer faces of the actual wall polygons against (0,0,width,height), not just the dimension annotations. draw_wall endpoints are centerlines; thickness extends perpendicular to the centerline only, with no end caps. Do not use a yard outline or dimension as a substitute for the confirmed wall envelope. openingEvidence.operationIndex must count ALL operations from zero; verify it references the intended insert_block after completing the operations array.";
   bool largePlan=Math.Max(width,height)>=30000;
   if(largePlan)prompt+="\nFor this large plan, aim for 180 operations or fewer. Prioritize the continuous wall network, openings, columns, stair cores, obvious room labels and the two overall dimensions. Omit decorative marks and redundant linework to complete the first reviewable draft.";
   var start=accounts.Start(profile,"exec","--ignore-user-config","--ignore-rules","--ephemeral","--skip-git-repo-check","--sandbox","read-only","--disable","shell_tool","--disable","unified_exec","--disable","multi_agent","--json","--image",source,"--output-schema",Path.Combine(config.ContentRoot,"schemas","image-plan.schema.json"),"-");
   string work=Path.Combine(config.DataRoot,"image-workspace");Directory.CreateDirectory(work);start.WorkingDirectory=work;
   using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);int timeLimitMinutes=largePlan?12:8;timeout.CancelAfter(TimeSpan.FromMinutes(timeLimitMinutes));
   using var process=Process.Start(start)??throw new CadException("AI_START_FAILED","Không gọi được AI trong app.");
   var errors=process.StandardError.ReadToEndAsync();string final="";JObject usage=new();string eventError="";bool completed=false,recovered=false;
   try{await process.StandardInput.WriteAsync(prompt.AsMemory(),timeout.Token);process.StandardInput.Close();while(await process.StandardOutput.ReadLineAsync(timeout.Token) is string line){var ev=Json.Read<JObject>(line);if(ev.Value<string>("type")=="item.completed"&&ev["item"]?.Value<string>("type")=="agent_message")final=ev["item"]!.Value<string>("text")??"";if(ev.Value<string>("type")=="turn.completed"){completed=true;usage=ev["usage"] as JObject??new();}if(ev.Value<string>("type")=="error")eventError=ev.Value<string>("message")??"AI error";}await process.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){if(!process.HasExited)process.Kill(true);ct.ThrowIfCancellationRequested();if(!completed||final=="")throw new CadException("AI_TIMEOUT",$"AI chưa hoàn tất sau {timeLimitMinutes} phút. Có thể bấm Chạy lại từ hàng đợi.");recovered=true;}
   _=await errors;if((!recovered&&process.ExitCode!=0)||final==""){Json.Atomic(Path.Combine(config.DataRoot,"last-image-ai-error.json"),new{at=DateTime.UtcNow,exitCode=process.ExitCode,eventError});throw new CadException("AI_FAILED","AI chưa trả kế hoạch ảnh hợp lệ. CAD chưa thay đổi.");}
   if(accounts.Epoch!=epoch)throw new CadException("AI_ACCOUNT_CHANGED","Tài khoản AI đổi trong lúc dựng ảnh.");
   var reply=Json.Read<JObject>(final);Json.Atomic(Path.Combine(workspace.Intelligence.Folder,sourceId+".ai-candidate.json"),new{sourceId,sourceHash=meta.Value<string>("hash"),width,height,imageRect,templateId,templateVersion=template.Version,skillId,skillVersion=skill.Version,reply,usage,at=DateTime.UtcNow});
   return SaveDraft(sourceId,width,height,imageRect,template,skill,reply,usage,meta,model);
  }catch(CadException error){Json.Atomic(Path.Combine(config.DataRoot,"last-image-plan-error.json"),new{at=DateTime.UtcNow,sourceId,code=error.Code,message=error.Message});throw;}finally{gate.Release();}
 }
 public async Task<JObject> RetryValidation(string sourceId,double width,double height,JObject imageRect,CancellationToken ct){if(!await gate.WaitAsync(0,ct))throw new CadException("AI_BUSY","Đang dựng nguồn.");try{Json.Id(sourceId);var candidate=Json.Read<JObject>(File.ReadAllText(Path.Combine(workspace.Intelligence.Folder,sourceId+".ai-candidate.json")));var meta=Json.Read<JObject>(File.ReadAllText(Path.Combine(workspace.Intelligence.Folder,sourceId+".json")));var model=Json.Read<JObject>(File.ReadAllText(workspace.Intelligence.AnalysisPath(sourceId)));string source=Path.Combine(workspace.Intelligence.Folder,sourceId+Path.GetExtension(meta.Value<string>("name")??""));if(Json.FileHash(source)!=meta.Value<string>("hash")||(candidate.Value<string>("sourceHash")??model.Value<string>("sourceHash"))!=meta.Value<string>("hash"))throw new CadException("SOURCE_CHANGED","Nguồn đã đổi, không dùng lại phản hồi AI.");var t=workspace.Template(candidate.Value<string>("templateId")??"");var skill=workspace.Store.Skill(candidate.Value<string>("skillId")??"");if(t.Version!=candidate.Value<string>("templateVersion")||skill.Version!=candidate.Value<string>("skillVersion")||skill.TemplateId!=t.Id)throw new CadException("RESOURCE_CHANGED","Thư viện hoặc Skill đã đổi.");if(width<1000||height<1000||width>100000||height>100000||(candidate.Value<double?>("width")??model["reviewMetadata"]?.Value<double?>("widthMm"))!=width||(candidate.Value<double?>("height")??model["reviewMetadata"]?.Value<double?>("heightMm"))!=height||(candidate["imageRect"] is JObject originalRect&&!JToken.DeepEquals(originalRect,imageRect)))throw new CadException("NEEDS_CALIBRATION","Giữ kích thước nguồn đã xác nhận khi kiểm tra lại.");return SaveDraft(sourceId,width,height,imageRect,t,skill,(JObject)candidate["reply"]!,(JObject?)candidate["usage"]??new(),meta,model);}finally{gate.Release();}}
 JObject SaveDraft(string sourceId,double width,double height,JObject imageRect,TemplateProfile template,SkillDefinition skill,JObject reply,JObject usage,JObject meta,JObject model,string method="APP_AI_IMAGE_PLAN"){string analysisPath=workspace.Intelligence.AnalysisPath(sourceId),metadata=Path.Combine(workspace.Intelligence.Folder,sourceId+".json");string templateId=template.Id,skillId=skill.Id;
var ops=reply["operations"]!.ToObject<List<Operation>>()!;if(ops.Count<20||ops.Count>350)throw new CadException("IMAGE_PLAN_LIMIT","Kế hoạch ảnh cần 20–350 thao tác.");
   AiOperationDefaults.Normalize(ops);
   bool fixedWindowDepth=skill.Id==ResidentialSourcePlan.SkillId&&AiOperationDefaults.UseCatalogWindowDepth(ops,template);
   foreach(var op in ops){Validation.Operation(op,template,true,true);foreach(var p in Validation.Bounds(op,template))if(p.X< -2500||p.X>width+5000||p.Y< -2500||p.Y>height+4000)throw new CadException("IMAGE_PLAN_BOUNDS","Chi tiết AI vượt vùng ảnh đã hiệu chuẩn.");}
   JArray? normalizedEvidence=null;
   if(skill.Id==ResidentialSourcePlan.SkillId)normalizedEvidence=SourceOpeningEvidence.NormalizeReferences(reply["openingEvidence"] as JArray??new(),ops,template);
   DraftingRules.Enforce(ops,skill.Recipe,template,true);string wallLayer=skill.Recipe?.Layers.TryGetValue("wall",out var wl)==true?wl:"A-WALL";var wallPoints=ops.Where(o=>o.Layer==wallLayer).SelectMany(o=>o.Kind=="draw_wall"?DraftingRules.Wall(o):o.Points).ToList();if(wallPoints.Count<8||Math.Abs(wallPoints.Min(p=>p.X))>20||Math.Abs(wallPoints.Max(p=>p.X)-width)>20||Math.Abs(wallPoints.Min(p=>p.Y))>20||Math.Abs(wallPoints.Max(p=>p.Y)-height)>20)throw new CadException("FOOTPRINT_MISMATCH","Tường AI chưa khớp kích thước bao được xác nhận.");
   string original=Path.Combine(workspace.Intelligence.Folder,sourceId+".auto-analysis.json");if(!File.Exists(original))File.Copy(analysisPath,original);
   var bounds=ops.SelectMany(o=>Validation.Bounds(o,template)).ToList();
   model["reviewOperations"]=JArray.FromObject(ops);model["openingEvidence"]=normalizedEvidence??reply["openingEvidence"]?.DeepClone();model["reviewSummary"]=reply["summary"];var notes=reply["assumptions"] as JArray??new();model["assumptions"]=notes.DeepClone();if(normalizedEvidence!=null&&!JToken.DeepEquals(normalizedEvidence,reply["openingEvidence"]))((JArray)model["assumptions"]!).Add("Đã liên kết lại chỉ số đối chiếu cửa theo block duy nhất khớp hai mép, bề rộng và đoạn tường; cần xem lại bản nháp.");if(fixedWindowDepth)((JArray)model["assumptions"]!).Add("Cửa sổ dùng chiều sâu khung theo Template; chiều dày tường vẫn theo bản nháp.");
   model["reviewMetadata"]=JObject.FromObject(new{requiresCatalogReview=skill.Recipe!=null&&ops.Any(o=>o.Kind=="insert_block"&&!skill.Recipe.AllowedBlocks.Contains(o.AssetId)),method,rotationUnits=reply.Value<string>("rotationUnits")??"unspecified",widthMm=width,heightMm=height,imageRect,templateId=template.Id,templateVersion=template.Version,skillId=skill.Id,skillVersion=skill.Version,usage,at=DateTime.UtcNow});
   model["bounds"]=JObject.FromObject(new{minX=bounds.Min(p=>p.X),minY=bounds.Min(p=>p.Y),maxX=bounds.Max(p=>p.X),maxY=bounds.Max(p=>p.Y)});model["status"]="AI_DRAFT_REVIEW_REQUIRED";
   Json.Atomic(analysisPath,model);meta["status"]="AI_DRAFT_REVIEW_REQUIRED";meta["analysisHash"]=Json.FileHash(analysisPath);Json.Atomic(metadata,meta);
   return model;
 }

